-- Golden Gate: Hyprland visual layer. Generated by rice-render from palette.toml.
-- Loaded from hyprland.lua via ~/.local/share/rice/active/hypr.lua.
--
-- Mac windows: one corner radius everywhere ({{ shape.window }}, squircle), a
-- hairline edge, large soft shadows (the focused window's stronger), springs.
-- The glass (hyprglass, Hyprland's blur or none) is `gg glass`'s, applied live
-- on top of this; the behaviour (binds, floating, gestures, plugins) is in
-- session.lua, which `gg` loads while Golden Gate is active.

hl.config({
    general = {
        gaps_in     = {{ shape.gaps_in }},
        gaps_out    = {{ shape.gaps_out }},
        border_size = {{ shape.border }},
    },

    decoration = {
        rounding         = {{ shape.window }},
        rounding_power   = {{ shape.rounding_power }},
        active_opacity   = 1.0,
        inactive_opacity = 1.0,
        -- inactive windows dim very slightly, as on the Mac
        dim_inactive     = true,
        dim_strength     = 0.04,
        dim_special      = 0.0,

        -- Frosted: Hyprland's blur, white-tinted and saturated (gg glass
        -- switches it off under hyprglass, and for Solid)
        blur = {
            enabled           = true,
            size              = 10,
            passes            = 4,
            new_optimizations = true,
            noise             = 0.012,
            vibrancy          = 0.25,
            vibrancy_darkness = 0.2,
            popups            = true,
            xray              = false,
        },

        shadow = {
            enabled      = true,
            render_power = 3,
            offset       = { 0, 12 },
        },
    },

    animations = { enabled = true },
})

---------------------------------------------------------------------------
-- Motion: springs (an overshoot, then rest), Spaces slide sideways
---------------------------------------------------------------------------
hl.curve("spring", { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} },  { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.curve("settle", { type = "bezier", points = { { {{ motion.settle.0 }}, {{ motion.settle.1 }} }, { {{ motion.settle.2 }}, {{ motion.settle.3 }} } } })
hl.curve("glide",  { type = "bezier", points = { { {{ motion.sink.0 }}, {{ motion.sink.1 }} },   { {{ motion.sink.2 }}, {{ motion.sink.3 }} } } })

-- speed is in deciseconds
hl.animation({ leaf = "windowsIn",    enabled = true, speed = {{ motion.open | div(100) }},  bezier = "spring", style = "popin 90%" })
hl.animation({ leaf = "windowsOut",   enabled = true, speed = {{ motion.close | div(100) }}, bezier = "glide",  style = "popin 94%" })
hl.animation({ leaf = "windowsMove",  enabled = true, speed = {{ motion.move | div(100) }},  bezier = "settle" })
hl.animation({ leaf = "fadeIn",       enabled = true, speed = {{ motion.open | div(100) }},  bezier = "glide" })
hl.animation({ leaf = "fadeOut",      enabled = true, speed = {{ motion.close | div(100) }}, bezier = "glide" })
hl.animation({ leaf = "fadeSwitch",   enabled = true, speed = {{ motion.focus | div(100) }}, bezier = "glide" })
hl.animation({ leaf = "fadeDim",      enabled = true, speed = {{ motion.focus | div(100) }}, bezier = "glide" })
hl.animation({ leaf = "border",       enabled = true, speed = {{ motion.focus | div(100) }}, bezier = "glide" })
-- Spaces: a horizontal slide
hl.animation({ leaf = "workspaces",   enabled = true, speed = {{ motion.workspace | div(100) }}, bezier = "glide", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = {{ motion.scratchpad | div(100) }}, bezier = "settle", style = "slidevert" })
-- the shell animates its own surfaces
hl.animation({ leaf = "layers",       enabled = true, speed = 2, bezier = "glide", style = "fade" })

---------------------------------------------------------------------------
-- Styling the base layer's window tags
---------------------------------------------------------------------------
-- content stays opaque; only the terminal is see-through (kitty's own background)
hl.window_rule({ name = "goldengate-opaque", match = { tag = "opaque" }, opacity = "1.0 override 1.0 override" })
hl.window_rule({ name = "goldengate-glassy", match = { tag = "glassy" }, opacity = "1.0 override 1.0 override" })
hl.window_rule({ name = "goldengate-dialog", match = { tag = "dialog" }, rounding = {{ shape.window }} })
hl.window_rule({ name = "goldengate-pip", match = { tag = "pip" }, border_size = 0 })
hl.window_rule({ name = "goldengate-fullscreen", match = { fullscreen = true }, border_size = 0, rounding = 0 })
hl.window_rule({
    name = "goldengate-game", match = { tag = "game" },
    no_anim = true, no_blur = true, no_shadow = true, opacity = "1.0 override 1.0 override",
})

---------------------------------------------------------------------------
-- The shell's surfaces: every one is goldengate:<part>. Frosted glass
-- blurs behind them (ignore_alpha keeps the soft shadows from frosting);
-- under Liquid, hyprglass takes the same list and Hyprland's blur stands down.
---------------------------------------------------------------------------
hl.layer_rule({
    name = "goldengate-glass",
    match = { namespace = "^goldengate:(menubar|island|dock|controlcenter|notifications|spotlight|widgets|osd|keys|launchpad|missioncontrol)$" },
    blur = true, ignore_alpha = 0.35, no_anim = true,
})
hl.layer_rule({ name = "goldengate-still", match = { namespace = "^goldengate:(wallpaper|desktop|hotcorner)$" }, no_anim = true })

---------------------------------------------------------------------------
-- The colours: the hairline, shadows, the glass's tint (in hypr-mode.lua)
---------------------------------------------------------------------------
local here = debug.getinfo(1, "S").source:match("^@(.*/)") or
    ((os.getenv("XDG_DATA_HOME") or (os.getenv("HOME") .. "/.local/share")) .. "/rice/active/")
dofile(here .. "hypr-mode.lua")

-- Golden Gate's behaviour while it's the active rice: its binds, floating
-- windows, gestures and plugins (session.lua, beside this file), then the
-- glass `gg glass` chose (glass.lua, from gg's state). `rice`
-- reloads Hyprland on a switch, which drops all of it for every other rice.
local function load(path)
    local f = io.open(path, "r")
    if not f then return end
    f:close()
    local ok, err = pcall(dofile, path)
    if not ok then print("goldengate: " .. path .. ": " .. tostring(err)) end
end
load(here .. "session.lua")
load(here .. "glass.lua")
